WITH gaps AS (SELECT *, CASE WHEN reading_ts - LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) > INTERVAL '45' MINUTE THEN 1 ELSE 0 END AS is_new_burst FROM device_readings), sessions_device_readings AS (SELECT *, SUM(is_new_burst) OVER (PARTITION BY device_code ORDER BY reading_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM gaps) SELECT id, device_code, reading_ts, temp_c, humidity, status_bits, island_id, CASE WHEN device_code RLIKE '^(DV-04|DV-03)$' THEN 'OTHER_ZONE' WHEN device_code RLIKE '^(DV-01|DV-02)$' THEN 'GROUP_A' ELSE 'CORE' END AS device_code_zone FROM sessions_device_readings ORDER BY humidity DESC;
